package com.mooncast.unified;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.provider.Settings;import android.view.*;import java.io.*;import java.util.concurrent.*;
/** Real WindowManager brightness/touch/compositor checks; no optical brightness, capture or TV claim. */
public final class ScreenDimDeviceTest {
 private final Instrumentation runner;private final Handler main=new Handler(Looper.getMainLooper());private volatile Messenger service;private int nonce;private final ConcurrentHashMap<Integer,CompletableFuture<Bundle>> replies=new ConcurrentHashMap<>();
 private final Messenger reply=new Messenger(new Handler(Looper.getMainLooper(),m->{CompletableFuture<Bundle> f=replies.remove(m.getData().getInt("nonce"));if(f!=null)f.complete(m.getData());return true;}));
 public ScreenDimDeviceTest(Instrumentation runner,Bundle args){this.runner=runner;}
 public void run(){Bundle out=new Bundle();int result=Activity.RESULT_CANCELED;Context context=runner.getTargetContext();Activity activity=null;ServiceConnection binding=null;StringBuilder proof=new StringBuilder();String originalOp=null;Intent fixture=new Intent().setClassName(context.getPackageName(),"com.mooncast.host.DimFixtureService");int saved=Settings.System.getInt(context.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,-1),mode=Settings.System.getInt(context.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,-1);
  try{
   require(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"disposable emulator only");
   originalOp=overlayMode(context.getPackageName());shell("appops set "+context.getPackageName()+" SYSTEM_ALERT_WINDOW allow");require(Settings.canDrawOverlays(context),"test overlay permission");
   activity=runner.startActivitySync(new Intent(context,DimFixtureActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runner.waitForIdleSync();
   context.startService(fixture);CountDownLatch ready=new CountDownLatch(1);
   binding=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){service=new Messenger(b);ready.countDown();}public void onServiceDisconnected(ComponentName n){service=null;}};
   require(context.bindService(fixture,binding,Context.BIND_AUTO_CREATE)&&ready.await(15,TimeUnit.SECONDS),"fixture binds");
   require(request(0).getBoolean("brightWakeLock"),"production-equivalent bright wake lock held");waitBrightness(.7f);pixels();checkpoint(proof,"baseline framework brightness and generated pixels: PASS\n");int before=DimFixtureActivity.touches.get();
   request(1);waitGuard();tap();SystemClock.sleep(3300);Bundle canceled=request(0);require(!canceled.getBoolean("active"),"countdown canceled: "+canceled+" underlyingTouches="+DimFixtureActivity.touches.get()+" baselineTouches="+before);waitBrightness(.7f);require(DimFixtureActivity.touches.get()==before,"cancel tap consumed");
   request(1);waitDim();pixels();require(DimFixtureActivity.resumed,"foreground content remains resumed");Activity focused=activity;boolean[] focus={false};runner.runOnMainSync(()->focus[0]=focused.hasWindowFocus());require(focus[0],"overlay does not steal foreground window focus");require(context.getSystemService(PowerManager.class).isInteractive(),"display remains interactive");
   Point size=new Point();activity.getWindowManager().getDefaultDisplay().getRealSize(size);float x=size.x*.25f,y=size.y*.6f;long down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,x,y);SystemClock.sleep(600);waitBrightness(.7f);require(request(0).getBoolean("active"),"guard remains while wake finger held");require(DimFixtureActivity.touches.get()==before,"wake DOWN not forwarded");touch(down,MotionEvent.ACTION_UP,x,y);SystemClock.sleep(300);require(!request(0).getBoolean("active"),"guard removed after complete wake");tap();require(DimFixtureActivity.touches.get()>before,"next fresh touch reaches content");checkpoint(proof,"cancel/wake/held-touch/fresh-touch: PASS\n");
   before=DimFixtureActivity.touches.get();request(1);waitDim();down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,x,y);multi(down,MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),x,y);multi(down,MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),x,y);require(request(0).getBoolean("active"),"multi-touch guard held until final UP");touch(down,MotionEvent.ACTION_UP,x,y);SystemClock.sleep(200);require(!request(0).getBoolean("active")&&DimFixtureActivity.touches.get()==before,"whole multi-touch wake consumed");
   request(1);waitDim();down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,x,y);touch(down,MotionEvent.ACTION_CANCEL,x,y);SystemClock.sleep(200);require(!request(0).getBoolean("active")&&DimFixtureActivity.touches.get()==before,"CANCEL retires guard without content touch");checkpoint(proof,"multi-touch/CANCEL: PASS\n");
   request(1);waitDim();request(2);waitBrightness(.7f);require(!request(0).getBoolean("active"),"explicit restore");SystemClock.sleep(3500);waitBrightness(.7f);checkpoint(proof,"manual restoration stays bright: PASS\n");
   request(1);waitDim();shell("appops set "+context.getPackageName()+" SYSTEM_ALERT_WINDOW deny");waitBrightness(.7f);long revokedDeadline=SystemClock.elapsedRealtime()+5000;while(request(0).getBoolean("active")&&SystemClock.elapsedRealtime()<revokedDeadline)SystemClock.sleep(100);require(!request(0).getBoolean("active"),"automatic permission-loss cleanup");shell("appops set "+context.getPackageName()+" SYSTEM_ALERT_WINDOW allow");SystemClock.sleep(3500);waitBrightness(.7f);require(!request(0).getBoolean("active"),"permission regrant never redims");checkpoint(proof,"overlay revocation drops brightness override: PASS\n");
   request(1);waitDim();shell("input keyevent 223");SystemClock.sleep(1000);shell("input keyevent 224");shell("wm dismiss-keyguard");waitBrightness(.7f);require(!request(0).getBoolean("active"),"screen off/wake never redims");checkpoint(proof,"screen-off broadcast clears override: PASS\n");
   request(1);waitDim();int pid=request(4).getInt("pid");waitBrightness(.7f);require(pid!=android.os.Process.myPid(),"independent owner killed");SystemClock.sleep(1000);pixels();checkpoint(proof,"owner process death removes dimming without helper: PASS\n");
   require(Settings.System.getInt(context.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,-1)==saved&&Settings.System.getInt(context.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,-1)==mode,"saved brightness settings unchanged");out.putString("stream","SCREEN_DIM_DEVICE_PASSED\n"+proof+"Scope: software WindowManager override/touch/screenshot only, not physical backlight, MediaProjection, Douyin or TV acceptance\n");result=Activity.RESULT_OK;
  }catch(Throwable failure){try{File dir=new File(context.getExternalFilesDir(null),"window-evidence");dir.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(dir,"window-at-failure.txt"))){f.write(shell("dumpsys window").getBytes(java.nio.charset.StandardCharsets.UTF_8));}}catch(Throwable ignored){}out.putString("stream","SCREEN_DIM_DEVICE_FAILED\n"+proof+android.util.Log.getStackTraceString(failure));}
  finally{
   try{if(service!=null)request(3);}catch(Throwable ignored){}
   if(binding!=null)try{context.unbindService(binding);}catch(Throwable failure){result=Activity.RESULT_CANCELED;cleanupFailure(out,failure);}
   try{context.stopService(fixture);}catch(Throwable failure){result=Activity.RESULT_CANCELED;cleanupFailure(out,failure);}
   if(activity!=null)try{Activity old=activity;runner.runOnMainSync(old::finish);}catch(Throwable failure){result=Activity.RESULT_CANCELED;cleanupFailure(out,failure);}
   try{if(originalOp!=null){shell("appops set "+context.getPackageName()+" SYSTEM_ALERT_WINDOW "+originalOp);require(originalOp.equals(overlayMode(context.getPackageName())),"original overlay mode restored");}}catch(Throwable failure){result=Activity.RESULT_CANCELED;cleanupFailure(out,failure);}
  }
  runner.finish(result,out);
 }
 private static void cleanupFailure(Bundle out,Throwable failure){out.putString("stream",out.getString("stream","").replace("SCREEN_DIM_DEVICE_PASSED","SCREEN_DIM_DEVICE_FAILED")+"\nCleanup failed: "+failure);}
 private void checkpoint(StringBuilder proof,String text){proof.append(text);android.util.Log.i("MoonCastWindowFixture",text);Bundle update=new Bundle();update.putString("stream",text);runner.sendStatus(0,update);}
 private Bundle request(int what)throws Exception{Messenger target=service;require(target!=null,"live fixture endpoint");int token=++nonce;CompletableFuture<Bundle> f=new CompletableFuture<>();replies.put(token,f);Message m=Message.obtain();m.what=what;m.replyTo=reply;Bundle b=new Bundle();b.putInt("nonce",token);m.setData(b);target.send(m);try{return f.get(5,TimeUnit.SECONDS);}finally{replies.remove(token);}}
 private void waitGuard()throws Exception{long end=SystemClock.elapsedRealtime()+2000;Bundle last=null;while(SystemClock.elapsedRealtime()<end){last=request(0);if(last.getBoolean("guardReady")){SystemClock.sleep(100);require(request(0).getBoolean("countdown"),"guard became ready within cancellable countdown");return;}SystemClock.sleep(50);}throw new AssertionError("guard layout readiness: "+last);}
 private void waitDim()throws Exception{long end=SystemClock.elapsedRealtime()+6000;while(SystemClock.elapsedRealtime()<end){if(request(0).getBoolean("dimmed")){waitBrightness(0);return;}SystemClock.sleep(100);}throw new AssertionError("dim countdown did not complete");}
 private void waitBrightness(float wanted)throws Exception{long end=SystemClock.elapsedRealtime()+5000;String last="";while(SystemClock.elapsedRealtime()<end){last=shell("dumpsys power");java.util.regex.Matcher m=java.util.regex.Pattern.compile("mScreenBrightnessOverrideFromWindowManager=([-0-9.]+)").matcher(last);if(m.find()){float actual=Float.parseFloat(m.group(1));float expected=Build.VERSION.SDK_INT<30?wanted*255f:wanted;if(actual>=0&&Math.abs(actual-expected)<(Build.VERSION.SDK_INT<30?.51f:.01f))return;}SystemClock.sleep(200);}throw new AssertionError("framework brightness override missing/wrong: expected="+wanted+"\n"+last);}
 private void pixels()throws Exception{
  long deadline=SystemClock.elapsedRealtime()+10000;String last="";
  do{Bitmap b=runner.getUiAutomation().takeScreenshot();require(b!=null,"compositor screenshot");int left=b.getPixel(b.getWidth()/4,b.getHeight()*3/5),right=b.getPixel(b.getWidth()*3/4,b.getHeight()*3/5);boolean valid=Color.red(left)>220&&Color.green(left)<40&&Color.blue(left)<40&&Color.blue(right)>220&&Color.green(right)<40&&Color.red(right)<40;last="size="+b.getWidth()+"x"+b.getHeight()+" left="+Integer.toHexString(left)+" right="+Integer.toHexString(right);
   if(!valid){File dir=new File(runner.getTargetContext().getExternalFilesDir(null),"window-evidence");require(dir.isDirectory()||dir.mkdirs(),"generated evidence directory");try(FileOutputStream f=new FileOutputStream(new File(dir,"generated-pixel-failure.png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}}
   b.recycle();if(valid)return;SystemClock.sleep(200);
  }while(SystemClock.elapsedRealtime()<deadline);
  throw new AssertionError("transparent guard preserves generated screenshot pixels: "+last);
 }
 private void tap(){Point size=new Point();runner.getTargetContext().getSystemService(WindowManager.class).getDefaultDisplay().getRealSize(size);float x=size.x*.25f,y=size.y*.6f;long down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,x,y);touch(down,MotionEvent.ACTION_UP,x,y);SystemClock.sleep(200);}
 private void multi(long down,int action,float x,float y){MotionEvent.PointerProperties[] pp={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] pc={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int i=0;i<2;i++){pp[i].id=i;pp[i].toolType=MotionEvent.TOOL_TYPE_FINGER;pc[i].x=x+i*30;pc[i].y=y;pc[i].pressure=1;pc[i].size=1;}MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,2,pp,pc,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);require(runner.getUiAutomation().injectInputEvent(e,true),"real multi-touch injection");e.recycle();}
 private String overlayMode(String pkg)throws Exception{String raw=shell("appops get "+pkg+" SYSTEM_ALERT_WINDOW");java.util.regex.Matcher mode=java.util.regex.Pattern.compile("SYSTEM_ALERT_WINDOW: (allow|deny|ignore|default|foreground)").matcher(raw);if(mode.find())return mode.group(1);require(raw.contains("No operations"),"known original AppOps mode: "+raw);return "default";}
 private void touch(long down,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);require(runner.getUiAutomation().injectInputEvent(e,true),"real touch injection");e.recycle();}
 private String shell(String cmd)throws Exception{try(ParcelFileDescriptor p=runner.getUiAutomation().executeShellCommand(cmd);InputStream in=new FileInputStream(p.getFileDescriptor());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>262144)throw new IOException("bounded shell output");}return out.toString("UTF-8");}}
 private static void require(boolean yes,String message){if(!yes)throw new AssertionError(message);}
}
